func (s *Store) ensureAdmin(ctx context.Context, email, password string) error {
	if email == "" {
		return nil
	}
	var id int64
	var hash string
	err := s.DB.QueryRowContext(ctx, `SELECT id, password_hash FROM users WHERE email=`+s.ph(1), email).Scan(&id, &hash)
	if errors.Is(err, sql.ErrNoRows) {
		if password == "" {
			password = "changeme123" // дев-дефолт; в проде пароль обязателен через env
		}
		return s.createAdmin(ctx, email, password)
	}
	if err != nil {
		return err
	}
	// ротация: непустой ADMIN_PASSWORD из env меняет пароль существующего админа
	// (так работает процедура из RUNBOOK — сменил env, рестартнул, пароль обновился)
	if password != "" && bcrypt.CompareHashAndPassword([]byte(hash), []byte(password)) != nil {
		newHash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
		if err != nil {
			return err
		}
		_, err = s.DB.ExecContext(ctx, `UPDATE users SET password_hash=`+s.ph(1)+`,updated_at=`+s.ph(2)+` WHERE id=`+s.ph(3),
			string(newHash), time.Now().UTC().Format(time.RFC3339), id)
		return err
	}
	return nil
}

func (s *Store) createAdmin(ctx context.Context, email, password string) error {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	now := time.Now().UTC().Format(time.RFC3339)
	_, err = s.DB.ExecContext(ctx, `INSERT INTO users (email,password_hash,name,role,created_at,updated_at) VALUES (`+s.phList(1, 6)+`)`,
		email, string(hash), "Сая", "admin", now, now)
	return err
}
